use js_runtime::{Runtime,Value,JsResult,EnvId};use js_runtime::property_slots::LiteralReadSite;
static LENGTH:LiteralReadSite=LiteralReadSite::new("length");
fn read(rt:&mut Runtime,value:Value)->f64{let Value::Number(n)=rt.get_literal_cached(value,&LENGTH).unwrap()else{panic!()};n}
#[test]fn fresh_array_lengths_follow_growth_shrink_readonly_and_maximum(){for enabled in[false,true]{let mut rt=Runtime::new();rt.literal_length_fast_path_enabled=enabled;let array=rt.array(&[]);assert_eq!(read(&mut rt,array).to_bits(),0);let key=rt.intern("7");rt.set(array,key,Value::Bool(true),true).unwrap();assert_eq!(read(&mut rt,array),8.0);let key=rt.intern("length");rt.set(array,key,Value::Number(2.0),true).unwrap();assert_eq!(read(&mut rt,array),2.0);rt.set(array,key,Value::Number(4294967295.0),true).unwrap();assert_eq!(read(&mut rt,array).to_bits(),4294967295.0f64.to_bits());}}
#[test]fn utf16_lengths_include_surrogate_units_and_boxed_values(){for enabled in[false,true]{let mut rt=Runtime::new();rt.literal_length_fast_path_enabled=enabled;let text=rt.string_utf16(&[97,0xd800,0xdc00,0xdfff]);let boxed=rt.to_object(text).unwrap();assert_eq!(read(&mut rt,text),4.0);assert_eq!(read(&mut rt,boxed),4.0);let empty=rt.string("");assert_eq!(read(&mut rt,empty).to_bits(),0);}}
fn rounds(rt:&mut Runtime,_:Value,_:&[Value],parent:EnvId)->JsResult<Value>{let env=rt.child_env(parent);for(name,n)in[("battles",23.0),("warmup",0.0),("battleIndex",0.0)]{rt.declare(env,name,Value::Number(n))?;}let initial=rt.objects.len();let mut seen=std::collections::HashSet::new();let mut reuse=false;for round in 0..23{let array=rt.array(&[Some(Value::Number(round as f64))]);reuse|=!seen.insert(rt.object_id(array)?);assert_eq!(read(rt,array),1.0);let text=rt.string_utf16(&[0xd800,0xdc00,round]);let boxed=rt.to_object(text)?;assert_eq!(read(rt,text),3.0);assert_eq!(read(rt,boxed),3.0);let object=rt.object();let key=rt.intern("length");rt.define_data(object,key,Value::Number(-0.0),true,true,true)?;assert_eq!(read(rt,object).to_bits(),(-0.0f64).to_bits());rt.assign(env,"battleIndex",Value::Number(round as f64),false)?;rt.collect_native_battle_backedge(env,parent)?;}assert!(reuse);assert!(rt.objects.len()<initial+16);Ok(Value::Number(rt.native_battle_gc_stats().collections as f64))}
#[test]fn twenty_three_collections_recycle_object_kinds_without_stale_lengths(){for enabled in[false,true]{let mut rt=Runtime::new();rt.literal_length_fast_path_enabled=enabled;let f=rt.make_closure(rounds,rt.global_env,0,"__nativeRun");rt.set_function_source(f,&include_str!("../src/native_battle_run.js").encode_utf16().collect::<Vec<_>>()).unwrap();rt.enable_native_battle_gc();assert_eq!(rt.call(f,Value::Undefined,&[]).unwrap(),Value::Number(23.0));}}
